const x=$input.first().json, b=x.body||{};
const fail=error=>[{json:{ok:false,data:null,error}}];
const uuid=/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
if(typeof b.message!=='string'||!b.message.trim()||b.message.length>2000||!uuid.test(b.empresa_id||'')) return fail('Mensaje o empresa inválidos.');
const auth=x.headers?.authorization || '';
if(!/^Bearer \S+$/i.test(auth)) return fail('Falta la sesión del usuario.');
if(!/^https:\/\/[a-z0-9-]+\.supabase\.co$/.test(x.supabase_url||'') || x.supabase_url.includes('TU-PROYECTO')) return fail('Configura la URL del mismo proyecto Supabase que usa React.');
return [{json:{ok:true,message:b.message.trim(),contexto:{empresa_id:b.empresa_id,access_token:auth.slice(7),supabase_url:x.supabase_url}}}];

const r=$input.first().json;
if(r.error||!Number.isInteger(r.statusCode)||r.statusCode<200||r.statusCode>=300||!Array.isArray(r.body)) return [{json:{ok:false,data:null,error:r.statusCode===401?'Sesión vencida. Inicia sesión nuevamente.':'Supabase rechazó la operación. Revisa permisos y conexión.'}}];
if(r.body.length!==1||!['admin','operador','lector'].includes(r.body[0].rol)) return [{json:{ok:false,data:null,error:'No perteneces a la empresa activa.'}}];
const x=$('Normalizar entrada').first().json;
return [{json:{ok:true,message:x.message,contexto:{...x.contexto,user_id:r.body[0].user_id,rol:r.body[0].rol}}}];

const x=$input.first().json;
const fail=error=>[{json:{ok:false,data:null,error}}];
if(x.error) return fail('El agente no pudo completar la solicitud. Revisa DeepSeek y sus herramientas.');
let o=x.output;
try {if(typeof o==='string') o=JSON.parse(o.trim().replace(/^```(?:json)?\s*/,'').replace(/\s*```$/,''));} catch {return fail('DeepSeek devolvió una respuesta que no cumple el contrato JSON.');}
if(!o||typeof o.ok!=='boolean') return fail('Respuesta de DeepSeek inválida.');
if(o.ok===false) return fail(typeof o.error==='string'&&o.error.trim()?o.error.slice(0,1000):'No se pudo completar la operación.');
if(!o.data||typeof o.data!=='object'||Array.isArray(o.data)||typeof o.data.message!=='string'||!o.data.message.trim()||o.error!==null) return fail('Respuesta de DeepSeek incompleta.');
return [{json:{ok:true,data:{message:o.data.message.slice(0,6000)},error:null}}];

const x=$input.first().json;
const fail=error=>[{json:{ok:false,data:null,error}}];
const c=x.contexto;
const uuid=/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const date=v=>typeof v==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(v)&&!Number.isNaN(Date.parse(v))&&new Date(v).toISOString().slice(0,10)===v;
if(!c||!uuid.test(c.empresa_id||'')||typeof c.access_token!=='string'||!c.access_token||!/^https:\/\/[a-z0-9-]+\.supabase\.co$/.test(c.supabase_url||'')) return fail('Contexto de sesión o Supabase inválido.');
const f=x.filtros??{};
if(typeof f!=='object'||Array.isArray(f)) return fail('filtros debe ser un objeto.');
const q=['empresa_id=eq.'+encodeURIComponent(c.empresa_id),'select=id,numero,fecha_emision,moneda,subtotal,impuesto,total,estado,proveedor_id,proveedores(nombre,identificacion)','order=fecha_emision.desc,id.asc'];
for(const k of Object.keys(f)) if(!['proveedor_id','numero','estado','fecha_desde','fecha_hasta','moneda','limite'].includes(k)) return fail('Filtro no permitido: '+k);
if(f.proveedor_id){if(!uuid.test(f.proveedor_id)) return fail('proveedor_id inválido.');q.push('proveedor_id=eq.'+encodeURIComponent(f.proveedor_id));}
if(f.numero){if(typeof f.numero!=='string'||f.numero.length>80) return fail('numero inválido.');q.push('numero=eq.'+encodeURIComponent(f.numero));}
if(f.estado){if(!['registrada','validada','rechazada'].includes(f.estado)) return fail('estado inválido.');q.push('estado=eq.'+f.estado);}
if(f.moneda){if(!['CRC','USD'].includes(f.moneda)) return fail('moneda inválida.');q.push('moneda=eq.'+f.moneda);}
for(const [k,op] of [['fecha_desde','gte'],['fecha_hasta','lte']]) if(f[k]){if(!date(f[k])) return fail(k+' inválida.');q.push('fecha_emision='+op+'.'+f[k]);}
if(f.fecha_desde&&f.fecha_hasta&&f.fecha_desde>f.fecha_hasta) return fail('Rango de fechas invertido.');
const limit=f.limite??50;
if(!Number.isInteger(limit)||limit<1||limit>100) return fail('limite debe ser un entero de 1 a 100.');
q.push('limit='+(limit+1));
return [{json:{ok:true,contexto:c,limite:limit,url:c.supabase_url+'/rest/v1/facturas?'+q.join('&')}}];

const r=$input.first().json;
if(r.error||!Number.isInteger(r.statusCode)||r.statusCode<200||r.statusCode>=300||!Array.isArray(r.body)) return [{json:{ok:false,data:null,error:r.statusCode===401?'Sesión vencida.':'Supabase rechazó la consulta. Revisa permisos y conexión.'}}];
const limite=$('Preparar consulta').first().json.limite;
const rows=r.body.slice(0,limite),totals={};
for(const f of rows){const [whole,fraction='']=Number(f.total).toFixed(2).split('.');totals[f.moneda]=(totals[f.moneda]||0n)+BigInt(whole)*100n+BigInt(fraction.padEnd(2,'0'));}
return [{json:{ok:true,data:{facturas:rows,total_por_moneda:Object.fromEntries(Object.entries(totals).map(([k,v])=>[k,(v/100n).toString()+'.'+(v%100n).toString().padStart(2,'0')])),cantidad:rows.length,hay_mas:r.body.length>limite,alcance:'Totales sólo sobre los registros devueltos. No mezclar monedas. El esquema no registra pagos: estos montos no representan deuda pendiente.'},error:null}}];

const x=$input.first().json,c=x.contexto;
const fail=error=>[{json:{ok:false,data:null,error}}];
const uuid=/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
if(!c||!uuid.test(c.empresa_id||'')||typeof c.access_token!=='string'||!c.access_token||!/^https:\/\/[a-z0-9-]+\.supabase\.co$/.test(c.supabase_url||'')) return fail('Contexto de sesión o Supabase inválido.');
if(!['admin','operador'].includes(c.rol)) return fail('Tu rol no permite registrar facturas.');
return [{json:{...x,ok:true}}];

const r=$input.first().json;
if(r.error||!Number.isInteger(r.statusCode)||r.statusCode<200||r.statusCode>=300||!Array.isArray(r.body)) return [{json:{ok:false,data:null,error:'No se pudo verificar el proveedor en Supabase.'}}];
if(r.body.length!==1) return [{json:{ok:false,data:null,error:'El proveedor no pertenece a la empresa activa.'}}];
return [{json:{ok:true,data:$('Revalidar factura').first().json.data,error:null}}];

const r=$input.first().json;
if(r.error||!Number.isInteger(r.statusCode)||r.statusCode<200||r.statusCode>=300||!Array.isArray(r.body)) return [{json:{ok:false,data:null,error:r.statusCode===409?'Ya existe esa factura o entra en conflicto con los datos existentes.':r.statusCode===401?'Sesión vencida.':'Supabase rechazó la operación. Revisa permisos, datos y conexión.'}}];
return [{json:{ok:true,data:{factura:r.body[0],message:'Factura registrada y revalidada por PostgreSQL.'},error:null}}];

const x=$input.first().json;
const fail=error=>[{json:{ok:false,data:null,error}}];
const c=x.contexto;
const uuid=/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const date=v=>typeof v==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(v)&&!Number.isNaN(Date.parse(v))&&new Date(v).toISOString().slice(0,10)===v;
if(!c||!uuid.test(c.empresa_id||'')||typeof c.access_token!=='string'||!c.access_token||!/^https:\/\/[a-z0-9-]+\.supabase\.co$/.test(c.supabase_url||'')) return fail('Contexto de sesión o Supabase inválido.');
const f=x.factura;
if(!f||typeof f!=='object'||Array.isArray(f)) return fail('factura es obligatoria.');
const errors=[];
if(!uuid.test(f.proveedor_id||'')) errors.push('proveedor_id debe ser UUID');
if(typeof f.numero!=='string'||f.numero.trim().length<1||f.numero.trim().length>80) errors.push('numero debe tener entre 1 y 80 caracteres');
const today=new Intl.DateTimeFormat('en-CA',{timeZone:'America/Costa_Rica',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
if(!date(f.fecha_emision)||f.fecha_emision>today) errors.push('fecha_emision inválida o futura');
if(!['CRC','USD'].includes(f.moneda)) errors.push('moneda debe ser CRC o USD');
const cents={};
for(const k of ['subtotal','impuesto','total']){const v=f[k];if((typeof v!=='number'&&typeof v!=='string')||!/^\d{1,12}(\.\d{1,2})?$/.test(String(v))||!Number.isFinite(Number(v))) errors.push(k+' debe ser un monto no negativo con máximo dos decimales');else cents[k]=Math.round(Number(v)*100);}
if(Object.keys(cents).length===3&&cents.total!==cents.subtotal+cents.impuesto) errors.push('total debe ser subtotal + impuesto, exactamente en centavos');
if(errors.length) return fail(errors.join('; '));
return [{json:{ok:true,data:{empresa_id:c.empresa_id,proveedor_id:f.proveedor_id,numero:f.numero.trim(),fecha_emision:f.fecha_emision,moneda:f.moneda,subtotal:cents.subtotal/100,impuesto:cents.impuesto/100,total:cents.total/100},error:null}}];

const x=$input.first().json,c=x.contexto;
const fail=error=>[{json:{ok:false,data:null,error}}];
const uuid=/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
if(!c||!uuid.test(c.empresa_id||'')||typeof c.access_token!=='string'||!c.access_token||!/^https:\/\/[a-z0-9-]+\.supabase\.co$/.test(c.supabase_url||'')) return fail('Contexto de sesión o Supabase inválido.');
const p=x.proveedor;
if(!p||typeof p!=='object'||Array.isArray(p)) return fail('proveedor debe ser un objeto.');
let filter;
if(p.id){if(!uuid.test(p.id)) return fail('id inválido.');filter='id=eq.'+encodeURIComponent(p.id);}
else if(p.identificacion){if(typeof p.identificacion!=='string'||p.identificacion.length>40) return fail('identificacion inválida.');filter='identificacion=eq.'+encodeURIComponent(p.identificacion);}
else if(typeof p.nombre==='string'&&p.nombre.trim().length>=2&&p.nombre.length<=160){const term=p.nombre.trim().replace(/[%*(),\\]/g,'');if(term.length<2) return fail('nombre inválido.');filter='nombre=ilike.'+encodeURIComponent('*'+term+'*');}
else return fail('Indica id, identificacion o nombre de mínimo 2 caracteres.');
return [{json:{ok:true,contexto:c,url:c.supabase_url+'/rest/v1/proveedores?select=id,nombre,identificacion&empresa_id=eq.'+encodeURIComponent(c.empresa_id)+'&'+filter+'&order=nombre.asc,id.asc&limit=21'}}];

const r=$input.first().json;
if(r.error||!Number.isInteger(r.statusCode)||r.statusCode<200||r.statusCode>=300||!Array.isArray(r.body)) return [{json:{ok:false,data:null,error:r.statusCode===401?'Sesión vencida.':'Supabase rechazó la búsqueda. Revisa permisos y conexión.'}}];
return [{json:{ok:true,data:{proveedores:r.body.slice(0,20),hay_mas:r.body.length>20},error:null}}];

const x=$input.first().json,c=x.contexto;
const fail=error=>[{json:{ok:false,data:null,error}}];
const uuid=/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
if(!c||!uuid.test(c.empresa_id||'')||typeof c.access_token!=='string'||!c.access_token||!/^https:\/\/[a-z0-9-]+\.supabase\.co$/.test(c.supabase_url||'')) return fail('Contexto de sesión o Supabase inválido.');
if(!['admin','operador'].includes(c.rol)) return fail('Tu rol no permite registrar proveedores.');
const p=x.proveedor;
if(!p||typeof p!=='object'||Array.isArray(p)||typeof p.nombre!=='string'||p.nombre.trim().length<2||p.nombre.trim().length>160) return fail('Nombre de proveedor inválido.');
const identificacion=p.identificacion==null||p.identificacion===''?null:p.identificacion;
if(identificacion!==null&&(typeof identificacion!=='string'||identificacion.trim().length<5||identificacion.trim().length>40)) return fail('Identificación debe tener entre 5 y 40 caracteres.');
return [{json:{ok:true,contexto:c,data:{empresa_id:c.empresa_id,nombre:p.nombre.trim(),identificacion:identificacion===null?null:identificacion.trim()}}}];

const r=$input.first().json;
if(r.error||!Number.isInteger(r.statusCode)||r.statusCode<200||r.statusCode>=300||!Array.isArray(r.body)) return [{json:{ok:false,data:null,error:r.statusCode===409?'Ya existe ese proveedor o entra en conflicto con los datos existentes.':r.statusCode===401?'Sesión vencida.':'Supabase rechazó la operación. Revisa permisos, datos y conexión.'}}];
return [{json:{ok:true,data:{proveedor:r.body[0],message:'Proveedor registrado.'},error:null}}];
